function periksaWorkflow(wf) {
  const masalah = [];
  if (!("on" in wf)) masalah.push("tidak ada pemicu");
  const jobs = wf.jobs ?? {};
  const nama = Object.keys(jobs);
  if (nama.length === 0) masalah.push("tidak ada job");
  for (const n of nama) {
    const job = jobs[n];
    if (!job["runs-on"]) masalah.push(`job ${n}: tidak ada runs-on`);
    const steps = job.steps ?? [];
    if (steps.length === 0) masalah.push(`job ${n}: tidak ada step`);
    steps.forEach((s, i) => {
      const label = `job ${n}, step ${i + 1}`;
      const punyaRun = "run" in s;
      const punyaUses = "uses" in s;
      if (punyaRun === punyaUses) masalah.push(`${label}: harus punya run atau uses`);
      else if (punyaUses && !String(s.uses).includes("@")) masalah.push(`${label}: uses tanpa versi`);
    });
    for (const perlu of [].concat(job.needs ?? [])) {
      if (!nama.includes(perlu)) masalah.push(`job ${n}: needs ke job tidak dikenal ${perlu}`);
    }
  }
  return masalah;
}

