function cocokTrigger(on, event, branch) {
  if (typeof on === "string") return on === event;
  if (Array.isArray(on)) return on.includes(event);
  if (!(event in on)) return false;
  const filter = on[event]?.branches;
  return filter ? filter.includes(branch) : true;
}

