solution.code:
function urutanJob(jobs) {
  const nama = Object.keys(jobs);
  const hasil = [];
  const selesai = new Set();
  while (hasil.length < nama.length) {
    const siap = nama.filter((n) => {
      if (selesai.has(n)) return false;
      const perlu = [].concat(jobs[n].needs ?? []);
      return perlu.every((p) => selesai.has(p));
    });
    if (siap.length === 0) throw new Error("siklus");
    for (const n of siap) {
      hasil.push(n);
      selesai.add(n);
    }
  }
  return hasil;
}

