solution.code:
function pilihCache(key, restoreKeys, tersimpan) {
  if (tersimpan.includes(key)) return key;
  for (const awalan of restoreKeys) {
    const cocok = tersimpan.filter((k) => k.startsWith(awalan));
    if (cocok.length) return cocok[cocok.length - 1];
  }
  return null;
}

