function jumlahJob(matrix) {
  const { exclude = [], include = [], ...sumbu } = matrix;
  const hasilKali = Object.values(sumbu).reduce((total, nilai) => total * nilai.length, 1);
  return hasilKali - exclude.length + include.length;
}

