function tagImage(repo, sha, ref) {
  const tags = [`${repo}:${sha.slice(0, 7)}`];
  const awalan = "refs/tags/v";
  if (ref.startsWith(awalan)) tags.push(`${repo}:${ref.slice(awalan.length)}`);
  return tags;
}

