solution.code:
function naikkanVersi(versi, jenis) {
  const [major, minor, patch] = versi.split(".").map(Number);
  if (jenis === "major") return `${major + 1}.0.0`;
  if (jenis === "minor") return `${major}.${minor + 1}.0`;
  return `${major}.${minor}.${patch + 1}`;
}

